resposta:
**Solução em Google Earth Engine**

A ideia é criar uma função que, para cada imagem da coleção, leia as duas propriedades (`WRS_PATH` e `WRS_ROW`), concatene‑as como texto e transforme o resultado em um número inteiro (ou decimal, se preferir). Esse número será usado como **banda** (banda de valores de pixel) na imagem final.

Abaixo está o código completo, com comentários explicativos:

```javascript
// ---------------------------------------------------------------
// Função que cria a banda concatenada a partir das propriedades
// ---------------------------------------------------------------
function createWRSBand(img) {
  // 1️⃣ Obtém os valores das propriedades
  var path = img.get('WRS_PATH');   // ex.: 218
  var row  = img.get('WRS_ROW');    // ex.: 70

  // Se alguma das propriedades não existir, retorna a imagem sem a banda
  if (path == null || row == null) {
    return img;   // ou retornar img.addBands(null) se quiser forçar um valor nulo
  }

  // 2️⃣ Converte para string e concatena (ex.: "21870")
  var concatStr = String(path).concat(String(row));

  // 3️⃣ Transforma a string concatenada em número (pode usar parseInt ou parseFloat)
  var concatNum = ee.Number.parseInt(concatStr);   // 21870

  // 4️⃣ Cria uma imagem constante com esse valor e adiciona à imagem original
  var band = ee.Image.constant(concatNum);          // banda 21870
  return img.addBands(band).toInt().rename('WRS_BAND');
}

// ---------------------------------------------------------------
// Uso: aplicar a função a toda a coleção de imagens
// ---------------------------------------------------------------

var L9coll = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
  .filterBounds(geometry2)               // sua geometria de região
  .filterDate(date_start, date_end)      // intervalo de datas desejado
  .map(createWRSBand);                   // executa a função em cada imagem
```

### O que o script faz passo a passo

| Etapa | Descrição |
|------|-----------|
| **1. Leitura das propriedades** | `img.get('WRS_PATH')` e `img.get('WRS_ROW')` retornam os valores armazenados nas metadados da imagem. |
| **2. Concatenção** | Converte ambos para `String` e une‑os (`"218" + "70"` → `"21870"`). |
